readme_description:
Given two nodes of a binary tree `p` and `q`, return *their* *lowest common ancestor (LCA)*.

Each node will have a reference to its parent node. The definition for `Node` is below:

```
class Node {
    public int val;
    public Node left;
    public Node right;
    public Node parent;
}
```

According to the **definition of LCA on Wikipedia**: "The lowest common ancestor of two nodes p and q in a tree T is the lowest node that has both p and q as descendants (where we allow a node to be a descendant of itself)."

helpers_content:
class TreeNodeP:
    def __init__(self, val: int = 0) -> None:
        self.val = val
        self.left: TreeNodeP | None = None
        self.right: TreeNodeP | None = None
        self.parent: TreeNodeP | None = None


def build_parent_tree(vals: list[int | None]) -> TreeNodeP | None:
    if not vals:
        return None
    v0 = vals[0]
    assert v0 is not None
    root = TreeNodeP(v0)
    queue: list[TreeNodeP] = [root]
    i = 1
    while queue and i < len(vals):
        node = queue.pop(0)
        if i < len(vals):
            v = vals[i]
            i += 1
            if v is not None:
                child = TreeNodeP(v)
                child.parent = node
                node.left = child
                queue.append(child)
        if i < len(vals):
            v = vals[i]
            i += 1
            if v is not None:
                child = TreeNodeP(v)
                child.parent = node
                node.right = child
                queue.append(child)
    return root


def find_node(root: TreeNodeP | None, val: int) -> TreeNodeP | None:
    if root is None:
        return None
    if root.val == val:
        return root
    return find_node(root.left, val) or find_node(root.right, val)

